@keyframes rise { from { opacity: 0; transform: translateY(16px); } }
.menu-kicker { font-size: 11px; letter-spacing: 0.42em; color: var(--khaki); }
h1 {
  font-family: var(--serif); font-weight: normal; margin: 10px 0 0;
  font-size: clamp(64px, 10vw, 132px); line-height: 0.88; letter-spacing: 0.02em;
  color: var(--paper); text-shadow: 0 6px 40px rgba(0,0,0,0.7);
}
h1 span {
  display: block; font-size: 0.52em; letter-spacing: 0.28em;
