}
.menu-rule { width: 86px; height: 3px; background: var(--red); margin: 22px 0 20px; }
.menu-desc {
  font-family: var(--serif); font-size: 15px; line-height: 1.65; color: #cdbf9f;
  max-width: 540px; margin: 0 0 20px;
}
.chips { display: flex; flex-wrap: wrap; gap: 7px; margin-bottom: 28px; }
.chips span {
  font-size: 9px; letter-spacing: 0.16em; padding: 5px 9px;
  border: 1px solid rgba(180, 154, 98, 0.5); color: var(--khaki);
  background: rgba(30, 26, 17, 0.5);
}
#start-btn { font-size: 14px; padding: 16px 52px; letter-spacing: 0.4em; }
#loading { margin-top: 12px; font-size: 9px; letter-spacing: 0.3em; color: var(--khaki); }
#loading.hidden { display: none; }
.menu-foot { margin-top: 26px; font-size: 8px; letter-spacing: 0.24em; color: rgba(200, 188, 158, 0.45); }

.menu-right { display: flex; flex-direction: column; gap: 22px; align-items: flex-end; animation: rise 1s 0.2s ease both; }
.stamp {
  border: 2px solid rgba(163, 57, 42, 0.8); padding: 12px 26px; text-align: center;
  transform: rotate(2.5deg); color: rgba(220, 120, 100, 0.9);
  background: rgba(30, 12, 8, 0.35);
}
.stamp-top, .stamp-sub { font-size: 8px; letter-spacing: 0.3em; }
.stamp-mid { font-family: var(--serif); font-size: 22px; letter-spacing: 0.14em; margin: 4px 0; }
.controls-card {
  width: 330px; padding: 20px 22px; background: rgba(16, 14, 9, 0.72);
  border: 1px solid var(--line); backdrop-filter: blur(6px);
}
.controls-title { font-size: 9px; letter-spacing: 0.3em; color: var(--khaki); margin-bottom: 10px; }
.controls-title.second { margin-top: 16px; border-top: 1px solid var(--line); padding-top: 14px; }
.ctrl { display: flex; justify-content: space-between; align-items: center; padding: 3px 0; font-size: 10px; color: var(--paper-dim); }
.ctrl kbd {
  font-family: var(--mono); font-size: 9px; color: var(--paper);
  border: 1px solid rgba(233, 222, 194, 0.3); padding: 2px 7px; min-width: 62px; text-align: center;
  background: rgba(233, 222, 194, 0.06);
}
.ctrl span { letter-spacing: 0.06em; }

/* ================= TOUCH ================= */
#touch-controls { display: none; }
body.is-touch.playing #touch-controls { display: block; }
body.is-touch #touch-controls.hidden { display: none; }
#touch-look {
  position: fixed; right: 0; top: 0; width: 52%; height: 100%;
  z-index: 6; touch-action: none;
}
#joy {
  position: fixed; left: 20px; bottom: 24px; width: 124px; height: 124px;
  border-radius: 50%; border: 2px solid rgba(233, 222, 194, 0.35);
  background: rgba(18, 15, 9, 0.35); z-index: 7; touch-action: none;
  display: flex; align-items: center; justify-content: center;
}
#joy-knob {
  width: 50px; height: 50px; border-radius: 50%;
  background: rgba(200, 182, 140, 0.55); border: 1px solid rgba(255,255,255,0.3);
}
#touch-buttons {
  position: fixed; right: 16px; bottom: 22px; z-index: 7;
  display: grid; grid-template-columns: 62px 62px; gap: 10px;
  align-items: end; justify-items: center;
}
.tbtn {
  width: 62px; height: 62px; border-radius: 50%;
  border: 1px solid rgba(233, 222, 194, 0.45);
  background: rgba(18, 15, 9, 0.55); color: var(--paper);
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em;
  touch-action: none;
}
.tbtn.small { width: 50px; height: 50px; font-size: 13px; }
.tbtn.fire {
  width: 82px; height: 82px; grid-column: span 2;
  background: rgba(163, 57, 42, 0.65); border-color: rgba(220, 120, 100, 0.7);
  font-size: 12px; letter-spacing: 0.16em;
}
.tbtn:active { background: rgba(200, 182, 140, 0.4); }

/* ================= RESPONSIVE ================= */
@media (max-width: 1080px) {
  .controls-card { width: 280px; }
  .menu-desc { font-size: 14px; }
}
@media (max-width: 820px) {
  .menu-content { flex-direction: column; justify-content: center; align-items: flex-start; padding: 5vh 7vw; gap: 3vh; overflow-y: auto; }
  .menu-right { flex-direction: row; align-items: flex-start; gap: 14px; width: 100%; }
  .controls-card { width: 100%; max-width: 340px; }
  .stamp { display: none; }
  h1 { font-size: clamp(54px, 14vw, 92px); }
  .menu-desc { font-size: 13px; max-width: 92vw; }
  .menu-foot { display: none; }
  #hud-top-left { left: 12px; top: 10px; min-width: 180px; padding: 8px 10px; }
  .sector { font-size: 8px; }
  .objective { font-size: 8px; }
  .score { font-size: 22px; }
  #minimap-wrap, #minimap { width: 112px; height: 112px; }
  #minimap-wrap { right: 12px; top: 10px; }
  .map-label { display: none; }
  #killfeed { top: 132px; right: 12px; width: 170px; }
  .feed-item { font-size: 8px; }
  #health-panel { left: 12px; bottom: 160px; min-width: 190px; padding: 7px 12px; }
  #weapon-panel { right: 12px; bottom: 160px; min-width: 150px; padding: 6px 10px; }
  #ammo { font-size: 24px; }
  #message { font-size: 13px; bottom: 118px; }
  #prompt { bottom: 150px; font-size: 9px; }
  #vehicle-panel { bottom: 195px; font-size: 8px; padding: 6px 10px; gap: 10px; }
  #compass { top: 10px; padding: 4px 10px; }
  .death-title { font-size: 40px; }
  body.is-touch #health-panel { bottom: 158px; }
  body.is-touch #weapon-panel { bottom: 158px; }
}
@media (max-height: 520px) {
  .menu-desc, .chips, .menu-foot { display: none; }
  h1 { font-size: 54px; }
  .controls-card { padding: 12px 14px; }
  .ctrl { font-size: 9px; }
}

