180:   setupTouch() {
181:     const joy = document.getElementById('joy');
182:     const knob = document.getElementById('joy-knob');
183:     const look = document.getElementById('touch-look');
184:     const fire = document.getElementById('btn-fire');
185:     const act = document.getElementById('btn-use');
186:     const rel = document.getElementById('btn-reload');
187:     const jump = document.getElementById('btn-jump');
188:     if (!joy) return;
189:     let joyId = null;
190:     const onJoy = (e) => {
191:       for (const t of e.changedTouches) {
192:         const r = joy.getBoundingClientRect();
193:         const dx = (t.clientX - (r.left + r.width / 2)) / (r.width / 2);
194:         const dy = (t.clientY - (r.top + r.height / 2)) / (r.height / 2);
195:         const len = Math.hypot(dx, dy) || 1;
196:         const cl = Math.min(1, len);
197:         this.touch.mx = dx / len * cl;
198:         this.touch.my = dy / len * cl;
199:         knob.style.transform = `translate(${this.touch.mx * 34}px, ${this.touch.my * 34}px)`;
200:         e.preventDefault();
201:       }
202:     };
203:     const endJoy = () => { this.touch.mx = 0; this.touch.my = 0; knob.style.transform = ''; };
204:     joy.addEventListener('touchstart', onJoy, { passive: false });
205:     joy.addEventListener('touchmove', onJoy, { passive: false });
206:     joy.addEventListener('touchend', endJoy);
207:     joy.addEventListener('touchcancel', endJoy);
208:     let lookId = null, lx = 0, ly = 0;
209:     look.addEventListener('touchstart', (e) => {
210:       const t = e.changedTouches[0]; lookId = t.identifier; lx = t.clientX; ly = t.clientY; e.preventDefault();
211:     }, { passive: false });
212:     look.addEventListener('touchmove', (e) => {
213:       for (const t of e.changedTouches) {
214:         if (t.identifier !== lookId) continue;
215:         const dx = t.clientX - lx, dy = t.clientY - ly;
216:         lx = t.clientX; ly = t.clientY;
217:         if (this.player.mode === 'plane') {
218:           this.flightStick.x = clamp(this.flightStick.x + dx * 0.01, -1, 1);
219:           this.flightStick.y = clamp(this.flightStick.y + dy * 0.01, -1, 1);
220:         } else {
221:           this.player.yaw -= dx * 0.004;
222:           this.player.pitch = clamp(this.player.pitch - dy * 0.004, -1.4, 1.4);
223:         }
224:         e.preventDefault();
225:       }
226:     }, { passive: false });
227:     const endLook = () => { lookId = null; };
228:     look.addEventListener('touchend', endLook);
229:     look.addEventListener('touchcancel', endLook);
230:     const bind = (el, down, up) => {
231:       el.addEventListener('touchstart', (e) => { e.preventDefault(); down(); }, { passive: false });
232:       el.addEventListener('touchend', (e) => { e.preventDefault(); up?.(); }, { passive: false });
233:       el.addEventListener('touchcancel', () => up?.());
234:     };
235:     bind(fire, () => { this.input.fire = true; }, () => { this.input.fire = false; });
236:     bind(act, () => this.interact());
237:     bind(rel, () => this.reload());
238:     bind(jump, () => this.tryJump());
239:   }
