324:   update(dt) {
325:     this.world.update(dt, this.time, this.player.pos);
326:     if (this.started) {
327:       this.ai.update(dt);
328:       for (const s of this.soldiers) s.update(dt);
329:       for (const t of this.tanks) t.update(dt);
330:       for (const p of this.planes) p.update(dt);
331:       for (const m of this.mgs) m.update(dt);
332:       for (let i = this.parachutes.length - 1; i >= 0; i--) {
333:         const p = this.parachutes[i];
334:         p.update(dt);
335:         if (p.landed) this.parachutes.splice(i, 1);
336:       }
337:       for (const r of this.ragdolls) r.update(dt);
338:       this.updatePlayer(dt);
339:       this.updateRespawns(dt);
340:       this.updateAmbient(dt);
341:       this.hud.update(dt);
342:     } else {
343:       // idle menu camera
344:       const p = this.player;
345:       p.yaw += Math.sin(this.time * 0.15) * dt * 0.06;
346:       this.updateCameraTransform(dt, true);
347:     }
348:     this.effects.update(dt);
349:     this.audio.update(dt, this.combatNearby());
350:   }
