352:   updateCameraTransform(dt, force = false) {
353:     const p = this.player;
354:     const cam = this.camera;
355:     if (p.mode === 'plane' && p.plane) {
356:       const pl = p.plane;
357:       const cockpit = new THREE.Vector3(0, 1.92, 0.5).applyQuaternion(pl.quat);
358:       cam.position.copy(pl.pos).add(cockpit);
359:       cam.quaternion.copy(pl.quat);
360:       // slight cockpit shake
361:       cam.position.y += Math.sin(this.time * 17) * 0.008;
362:       cam.fov = lerp(cam.fov, 70, 0.1);
363:       cam.updateProjectionMatrix();
364:       return;
365:     }
366:     if (p.mode === 'parachute' && p.chute) {
367:       const c = p.chute;
368:       cam.position.copy(c.pos).add(new THREE.Vector3(0, -1.6, 0));
369:       cam.rotation.set(p.pitch, p.yaw, Math.sin(this.time * 1.2) * 0.05);
370:       return;
371:     }
372:     if (p.mode === 'mg' && p.mg) {
373:       const mg = p.mg;
374:       _dir.set(-Math.sin(p.yaw) * Math.cos(p.pitch), Math.sin(p.pitch), -Math.cos(p.yaw) * Math.cos(p.pitch));
375:       cam.position.copy(mg.pos).add(new THREE.Vector3(0, 1.55, 0)).addScaledVector(_dir, -1.25);
376:       cam.rotation.set(p.pitch, p.yaw, 0);
377:       return;
378:     }
379:     if (p.mode === 'tank' && p.tank) {
380:       const seat = p.tank.getSeatWorld('gunnerL');
381:       cam.position.copy(seat).add(new THREE.Vector3(0, 0.15, 0));
382:       cam.rotation.set(p.pitch, p.yaw, 0);
383:       return;
384:     }
385:     // foot / dead
386:     const bob = p.mode === 'foot' ? Math.sin(p.bob * 2) * 0.028 * Math.min(1, p.speedFactor || 0) : 0;
387:     const shake = this.effects.shake;
388:     const eye = p.crouch ? 1.12 : 1.68;
389:     cam.position.set(
390:       p.pos.x + (Math.random() - 0.5) * shake * 0.06,
391:       p.pos.y + eye + bob + (p.dead ? -0.7 : 0) + (Math.random() - 0.5) * shake * 0.05,
392:       p.pos.z + (Math.random() - 0.5) * shake * 0.06,
393:     );
394:     cam.rotation.set(p.pitch + shake * 0.006 * Math.sin(this.time * 40), p.yaw, shake * 0.004 * Math.sin(this.time * 31));
395:     if (p.dead) cam.rotation.z = 0.5;
396:     const targetFov = p.ads && p.mode === 'foot' ? 52 : this.baseFov;
397:     cam.fov = lerp(cam.fov, targetFov, 1 - Math.exp(-10 * dt));
398:     cam.updateProjectionMatrix();
399:   }
