401:   updatePlayer(dt) {
402:     const p = this.player;
403:     const h = this.hud;
404:     this.playerTarget.x = p.pos.x; this.playerTarget.z = p.pos.z;
405:     this.playerTarget.y = p.pos.y; this.playerTarget.dead = p.dead;
406:     this.playerTarget.headY = p.mode === 'parachute' ? 0 : 1.5;
407:     if (p.dead) {
408:       p.deathTimer -= dt;
409:       if (p.deathTimer <= 0) this.respawnPlayer();
410:       this.updateCameraTransform(dt);
411:       return;
412:     }
413:     if (p.damageT > 0) p.damageT -= dt;
414:     else if (p.hp < p.maxHp && p.mode === 'foot') p.hp = Math.min(p.maxHp, p.hp + dt * 2.2);
415:     if (p.reloading > 0) {
416:       p.reloading -= dt;
417:       if (p.reloading <= 0) { p.ammo = 10; p.reserve -= 10; h.message('', 0); }
418:     }
419:     p.fireCd = Math.max(0, p.fireCd - dt);
420:     p.kick = Math.max(0, p.kick - dt * 6);
421:     // flight stick recenter
422:     if (this.flightStick.active) {
423:       this.flightStick.x = damp(this.flightStick.x, 0, 1.2, dt);
424:       this.flightStick.y = damp(this.flightStick.y, 0, 1.2, dt);
425:     }
426: 
427:     if (p.mode === 'foot') this.updateFoot(dt);
428:     else if (p.mode === 'plane') this.updatePlanePlayer(dt);
429:     else if (p.mode === 'parachute') this.updateChutePlayer(dt);
430:     else if (p.mode === 'mg') this.updateMGPlayer(dt);
431:     else if (p.mode === 'tank') this.updateTankPlayer(dt);
432: 
433:     this.updateCameraTransform(dt);
434:     this.updateViewmodel(dt);
435:     // interaction prompt
436:     const it = this.findInteractable();
437:     h.setPrompt(it ? it.label : '');
438:     this.playerTarget.x = p.pos.x; this.playerTarget.z = p.pos.z; this.playerTarget.y = p.pos.y;
439:   }
