441:   updateFoot(dt) {
442:     const p = this.player;
443:     let f = 0, r = 0;
444:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) f += 1;
445:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) f -= 1;
446:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) r += 1;
447:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) r -= 1;
448:     f += -this.touch.my;
449:     r += this.touch.mx;
450:     const sprint = this.keys.has('ShiftLeft') && !p.ads;
451:     const speed = (p.crouch ? 2.2 : sprint ? 7.2 : 4.4) * (p.ads ? 0.55 : 1);
452:     const len = Math.hypot(f, r);
453:     if (len > 1) { f /= len; r /= len; }
454:     const fx = -Math.sin(p.yaw), fz = -Math.cos(p.yaw);
455:     const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
456:     let vx = (fx * f + rx * r) * speed;
457:     let vz = (fz * f + rz * r) * speed;
458:     p.speedFactor = damp(p.speedFactor || 0, Math.hypot(f, r), 8, dt);
459:     if (p.ads) p.speedFactor = 0;
460:     p.pos.x += vx * dt;
461:     p.pos.z += vz * dt;
462:     // colliders
463:     for (const c of this.world.colliders) {
464:       const dx = p.pos.x - c.x, dz = p.pos.z - c.z, rr = c.r + 0.35;
465:       const d2 = dx * dx + dz * dz;
466:       if (d2 < rr * rr && d2 > 0.0001) {
467:         const d = Math.sqrt(d2);
468:         p.pos.x = c.x + dx / d * rr;
469:         p.pos.z = c.z + dz / d * rr;
470:       }
471:     }
472:     for (const t of this.tanks) {
473:       if (!t.alive) continue;
474:       const dx = p.pos.x - t.pos.x, dz = p.pos.z - t.pos.z;
475:       const d2 = dx * dx + dz * dz;
476:       if (d2 < 9.5 && d2 > 0.01) {
477:         const d = Math.sqrt(d2);
478:         p.pos.x = t.pos.x + dx / d * 3.1;
479:         p.pos.z = t.pos.z + dz / d * 3.1;
480:       }
481:     }
482:     p.pos.x = clamp(p.pos.x, WORLD.minX + 3, WORLD.maxX - 3);
483:     p.pos.z = clamp(p.pos.z, WORLD.minZ + 3, WORLD.maxZ - 3);
484:     // vertical / jump
485:     const ground = heightAt(p.pos.x, p.pos.z);
486:     if (!p.grounded) {
487:       p.vy -= 19 * dt;
488:       p.jumpY += p.vy * dt;
