669:   /* ---------------- targeting ---------------- */
670:   raycastTargets(origin, dir, maxDist, team) {
671:     let best = { dist: maxDist, entity: null, point: origin.clone().addScaledVector(dir, maxDist), head: false, module: null };
672:     // terrain march
673:     for (let t = 1; t < maxDist; t += 2.2) {
674:       const x = origin.x + dir.x * t, y = origin.y + dir.y * t, z = origin.z + dir.z * t;
675:       if (y < heightAt(x, z)) {
676:         best.dist = t;
677:         best.point.set(x, y, z);
678:         best.entity = null;
679:         break;
680:       }
681:     }
682:     const test = (cx, cy, cz, r, entity, head = false, module = null) => {
683:       const ox = cx - origin.x, oy = cy - origin.y, oz = cz - origin.z;
684:       const tca = ox * dir.x + oy * dir.y + oz * dir.z;
685:       if (tca < 0 || tca > best.dist) return;
686:       const d2 = ox * ox + oy * oy + oz * oz - tca * tca;
687:       if (d2 > r * r) return;
688:       const thc = Math.sqrt(r * r - d2);
689:       const t = tca - thc;
690:       if (t < 0 || t > best.dist) return;
691:       best.dist = t; best.entity = entity; best.head = head; best.module = module;
692:       best.point.set(origin.x + dir.x * t, origin.y + dir.y * t, origin.z + dir.z * t);
693:     };
694:     for (const s of this.soldiers) {
695:       if (s.dead || s.inVehicle || s.team === team) continue;
696:       test(s.x, s.y + 1.05, s.z, 0.42, s);
697:       test(s.x, s.y + 1.73, s.z, 0.2, s, true);
698:     }
699:     for (const t of this.tanks) {
700:       if (!t.alive || t.team === team) continue;
701:       test(t.pos.x, t.pos.y + 1.4, t.pos.z, 3.4, t);
702:     }
703:     for (const p of this.planes) {
704:       if (!p.alive || p.team === team) continue;
705:       const fwd = p.forward, right = new THREE.Vector3(1, 0, 0).applyQuaternion(p.quat);
706:       test(p.pos.x, p.pos.y + 1.2, p.pos.z, 2.1, p, false, 'engine');
707:       test(p.pos.x + right.x * 2.6, p.pos.y + 1.2 + right.y * 2.6, p.pos.z + right.z * 2.6, 1.3, p, false, 'wingL');
708:       test(p.pos.x - right.x * 2.6, p.pos.y + 1.2 - right.y * 2.6, p.pos.z - right.z * 2.6, 1.3, p, false, 'wingR');
709:       test(p.pos.x - fwd.x * 2.2, p.pos.y + 1.2, p.pos.z - fwd.z * 2.2, 1.0, p, false, 'tail');
710:     }
711:     return best.entity || best.point ? best : null;
712:   }
