714:   lineBlocked(from, to) {
715:     const d = to.clone().sub(from);
716:     const dist = d.length();
717:     if (dist < 1) return null;
718:     d.divideScalar(dist);
719:     for (let t = 4; t < dist - 2; t += 3.5) {
720:       const x = from.x + d.x * t, y = from.y + d.y * t, z = from.z + d.z * t;
721:       if (y < heightAt(x, z) + 0.05) return new THREE.Vector3(x, y, z);
722:     }
723:     return null;
724:   }
