726:   hasLineOfSight(a, b) {
727:     const from = new THREE.Vector3(a.x, (a.y ?? heightAt(a.x, a.z)) + 1.5, a.z);
728:     const to = new THREE.Vector3(b.x, (b.y ?? heightAt(b.x, b.z)) + (b.headY ?? 1.3), b.z);
729:     return !this.lineBlocked(from, to);
730:   }
