732:   findTarget(team, x, z, range) {
733:     let best = null, bestD = range;
734:     let bestNoLos = null, bestNoLosD = range;
735:     for (const s of this.soldiers) {
736:       if (s.team === team || s.dead || s.inVehicle) continue;
737:       const d = Math.hypot(s.x - x, s.z - z);
738:       if (d > range) continue;
739:       if (this.hasLineOfSight({ x, z, y: heightAt(x, z) }, s)) {
740:         if (d < bestD) { best = s; bestD = d; }
741:       } else if (d < bestNoLosD) { bestNoLos = s; bestNoLosD = d; }
742:     }
743:     const p = this.player;
744:     if (!p.dead && (p.mode === 'foot' || p.mode === 'mg' || p.mode === 'tank') && team !== 'british') {
745:       const d = Math.hypot(p.pos.x - x, p.pos.z - z);
746:       if (d < range) {
747:         this.playerTarget.running = (p.speedFactor || 0) > 0.4;
748:         this.playerTarget.inTrench = inTrench(p.pos.x, p.pos.z);
749:         if (this.hasLineOfSight({ x, z, y: heightAt(x, z) }, this.playerTarget)) {
750:           if (d < bestD) { best = this.playerTarget; bestD = d; }
751:         } else if (d < bestNoLosD) { bestNoLos = this.playerTarget; bestNoLosD = d; }
752:       }
753:     }
754:     return best || bestNoLos;
755:   }
