808:   /* ---------------- interactions ---------------- */
809:   findInteractable() {
810:     const p = this.player;
811:     if (p.dead) return null;
812:     if (p.mode === 'mg') return { type: 'exit', label: 'E — отпустить пулемёт' };
813:     if (p.mode === 'tank') return { type: 'exit', label: 'E — выйти из танка' };
814:     if (p.mode === 'plane') return { type: p.plane?.onGround ? 'exitplane' : 'bail', label: p.plane?.onGround ? 'E — выйти из самолёта' : 'E — прыгнуть с парашютом' };
815:     if (p.mode !== 'foot') return null;
816:     let best = null, bestD = 6.5;
817:     for (const mg of this.mgs) {
818:       if (mg.mountedBy) continue;
819:       const d = Math.hypot(p.pos.x - mg.pos.x, p.pos.z - mg.pos.z);
820:       if (d < 2.8 && d < bestD) { best = { type: 'mg', obj: mg, label: 'E — встать за пулемёт' }; bestD = d; }
821:     }
822:     for (const t of this.tanks) {
823:       if (!t.alive || t.playerAboard) continue;
824:       const d = Math.hypot(p.pos.x - t.pos.x, p.pos.z - t.pos.z);
825:       if (d < 7 && d < bestD) { best = { type: 'tank', obj: t, label: 'E — залезть в танк (стрелок)' }; bestD = d; }
826:     }
827:     for (const pl of this.planes) {
828:       if (!pl.alive || pl.pilot) continue;
829:       const d = Math.hypot(p.pos.x - pl.pos.x, p.pos.z - pl.pos.z);
830:       if (d < 6.5 && d < bestD) { best = { type: 'plane', obj: pl, label: 'E — сесть в самолёт' }; bestD = d; }
831:     }
832:     return best;
833:   }
