51:   get forward() { return _v1.set(Math.sin(this.yaw), 0, Math.cos(this.yaw)).clone(); }
52: 
53:   muzzlePos(out = new THREE.Vector3()) {
54:     const f = Math.sin(this.yaw), c = Math.cos(this.yaw);
55:     out.set(this.x + f * 0.95, this.y + 1.35 + Math.sin(this.aimPitch) * 0.5, this.z + c * 0.95);
56:     return out;
57:   }
58: 
59:   setMove(dx, dz, run = false) {
60:     this.moveDir.set(dx, dz);
61:     if (dx * dx + dz * dz > 0.001) this.moveDir.normalize();
62:     this.running = run;
63:   }
64: 
65:   setAim(target) {
66:     if (!target) return;
67:     const dx = target.x - this.x, dz = target.z - this.z;
68:     const dy = (target.y ?? this.y + 1.4) - (this.y + 1.45);
69:     this.aimYaw = Math.atan2(dx, dz);
70:     const dist = Math.sqrt(dx * dx + dz * dz) || 1;
71:     this.aimPitch = Math.atan2(dy, dist);
72:   }
73: 
74:   fireAt(target) {
75:     if (this.dead || this.cooldown > 0 || !target) return;
76:     const from = this.muzzlePos();
77:     const to = new THREE.Vector3(target.x, (target.y ?? this.y) + (target.headY ?? 1.3), target.z);
78:     const dist = from.distanceTo(to);
79:     const spread = clamp(dist / 260, 0.02, 0.2);
80:     to.x += (Math.random() - 0.5) * dist * spread;
81:     to.y += (Math.random() - 0.5) * dist * spread * 0.7;
82:     to.z += (Math.random() - 0.5) * dist * spread;
83:     const blocked = this.game.lineBlocked(from, to);
84:     if (blocked) to.copy(blocked);
85:     this.game.effects.tracer(from, to, this.team === 'british' ? 0xffd68a : 0xffa15c);
86:     this.game.effects.muzzle(from, _v2.copy(to).sub(from).normalize(), 0.75);
87:     this.game.audio?.shot(this.team, from, 0.5);
88:     this.recoil = 1;
89:     this.cooldown = this.role === 'mg' ? 0.09 : 1.15 + Math.random() * 0.8;
90:     // accuracy model
91:     let chance = clamp(0.46 - dist / 240, 0.05, 0.46);
92:     if (target.running) chance *= 0.62;
93:     if (target.inTrench) chance *= 0.7;
94:     if (this.role === 'mg') chance *= 0.55;
95:     if (!blocked && Math.random() < chance) {
96:       const dmg = this.role === 'mg' ? 8 : (14 + Math.random() * 8);
97:       target.hit?.(dmg, from, _v3.copy(to).sub(from).normalize());
98:     } else {
99:       this.game.effects.impactDirt(to, 0.6);
100:     }
101:   }
102: 
103:   hit(dmg, from, dir) {
104:     if (this.dead) return;
105:     this.hp -= dmg;
106:     this.suppressed = 1;
107:     this.game.effects.blood(new THREE.Vector3(this.x, this.y + 1.2, this.z), dir || UP);
108:     if (this.hp <= 0) this.die(dir, from);
109:   }
110: 
111:   die(dir, from) {
112:     if (this.dead) return;
113:     this.dead = true;
114:     this.group.visible = false;
115:     if (this.mounted) this.mounted.dismount();
116:     if (this.inVehicle) this.inVehicle = null;
117:     const imp = (dir ? dir.clone() : new THREE.Vector3(0, 1, 0)).multiplyScalar(4.5);
118:     this.game.addRagdoll(this, imp);
119:     this.game.onSoldierDied(this);
120:   }
121: 
122:   update(dt) {
123:     if (this.dead || this.inVehicle) return;
124:     const moving = this.moveDir.lengthSq() > 0.001;
125:     this.animSpeed = damp(this.animSpeed, moving ? (this.running ? 1.5 : 1) : 0, 8, dt);
126:     if (moving) {
127:       const spd = this.running ? 5.1 : this.speed;
128:       const speedMul = this.inTrench ? 0.72 : 1;
129:       this.x += this.moveDir.x * spd * speedMul * dt;
130:       this.z += this.moveDir.y * spd * speedMul * dt;
131:       this.yaw = dampAngle(this.yaw, Math.atan2(this.moveDir.x, this.moveDir.y), 8, dt);
132:     }
133:     // collisions with camp props
134:     for (const c of this.game.world.colliders) {
135:       const dx = this.x - c.x, dz = this.z - c.z;
136:       const rr = c.r + 0.3;
137:       const d2 = dx * dx + dz * dz;
138:       if (d2 < rr * rr && d2 > 0.0001) {
139:         const d = Math.sqrt(d2);
140:         this.x = c.x + dx / d * rr;
141:         this.z = c.z + dz / d * rr;
142:       }
143:     }
144:     // avoid tanks
145:     for (const t of this.game.tanks) {
146:       if (!t.alive) continue;
147:       const dx = this.x - t.pos.x, dz = this.z - t.pos.z;
148:       const d2 = dx * dx + dz * dz;
149:       if (d2 < 9 && d2 > 0.01) {
150:         const d = Math.sqrt(d2);
151:         this.x = t.pos.x + dx / d * 3;
152:         this.z = t.pos.z + dz / d * 3;
153:       }
154:     }
155:     this.x = clamp(this.x, WORLD.minX + 4, WORLD.maxX - 4);
156:     this.z = clamp(this.z, WORLD.minZ + 4, WORLD.maxZ - 4);
157:     const ground = heightAt(this.x, this.z);
158:     this.y = ground;
159:     this.inTrench = trenchDepthAt(this.x, this.z) > 0.8;
160:     this.group.position.set(this.x, this.y, this.z);
161:     if (!moving) this.yaw = dampAngle(this.yaw, this.aimYaw, 5, dt);
162:     this.group.rotation.y = this.yaw;
163:     if (this.cooldown > 0) this.cooldown -= dt;
164:     if (this.recoil > 0) this.recoil = Math.max(0, this.recoil - dt * 5);
165:     if (this.suppressed > 0) this.suppressed = Math.max(0, this.suppressed - dt * 0.3);
166:     this.animate(dt, moving);
167:     if (this.wantFire && this.fireTarget && !this.game.isDead(this.fireTarget)) {
168:       if (this.fireTarget.isPlane) {
169:         const d = this.fireTarget.pos.distanceTo(new THREE.Vector3(this.x, this.y + 1.4, this.z));
170:         if (d < 230) this.fireAt({ x: this.fireTarget.pos.x, y: this.fireTarget.pos.y, z: this.fireTarget.pos.z, headY: 0, isPlane: true });
171:       } else if (Math.random() < 0.65) {
172:         this.fireAt(this.fireTarget);
173:       }
174:     }
175:   }
176: 
177:   animate(dt, moving) {
178:     const u = this.group.userData;
179:     const B = u.bones;
180:     u.phase += dt * (2.2 + this.animSpeed * 5.2);
181:     const ph = u.phase;
182:     const s = Math.sin(ph), c = Math.cos(ph);
183:     const amt = this.animSpeed;
184:     const aim = this.wantFire || this.aimPitch !== 0;
185:     // base
186:     B.root.position.y = 0.93 + Math.abs(s) * 0.035 * amt;
187:     B.spine.rotation.set(0.03 + Math.sin(ph * 2) * 0.015 * (1 - amt), 0, 0);
188:     B.head.rotation.set(0, Math.sin(ph * 0.4) * 0.18, 0);
189:     B.weapon.rotation.x = -this.aimPitch * 0.9;
190:     B.weapon.rotation.y = 0;
191:     // legs
192:     B.legL.rotation.x = s * 0.6 * amt;
193:     B.legR.rotation.x = -s * 0.6 * amt;
194:     B.shinL.rotation.x = Math.max(0, -s) * 0.7 * amt + 0.05;
195:     B.shinR.rotation.x = Math.max(0, s) * 0.7 * amt + 0.05;
196:     B.footL.rotation.x = -0.1 - Math.max(0, -s) * 0.2 * amt;
197:     B.footR.rotation.x = -0.1 - Math.max(0, s) * 0.2 * amt;
198:     // arms hold rifle forward
199:     const sway = Math.sin(ph) * 0.06 * amt;
200:     B.armL.rotation.set(-1.15 + sway, 0.15, 0.35);
201:     B.armR.rotation.set(-1.2 - sway, -0.1, -0.32);
202:     B.foreL.rotation.set(-0.5, 0, -0.2);
203:     B.foreR.rotation.set(-0.65, 0, 0.15);
204:     B.handL.rotation.set(0, 0, 0);
205:     B.handR.rotation.set(0, 0, 0);
206:     if (!aim) {
207:       // patrol carry: rifle angled across chest
208:       B.weapon.rotation.x = -0.35;
209:       B.armL.rotation.set(-0.75 + sway, 0.1, 0.2);
210:       B.armR.rotation.set(-0.8 - sway, -0.1, -0.2);
211:     }
212:     // recoil
213:     B.spine.rotation.x += this.recoil * 0.08;
214:     B.armL.rotation.x += this.recoil * 0.15;
215:     B.armR.rotation.x += this.recoil * 0.15;
216:   }
217: }
