248:   mount(entity) {
249:     if (this.mountedBy) return false;
250:     this.mountedBy = entity;
251:     entity.mounted = this;
252:     if (entity.isPlayer) {
253:       this.playerMounted = true;
254:     } else {
255:       // stand behind the gun
256:       entity.x = this.site.x - Math.sin(this.baseYaw) * 0.75;
257:       entity.z = this.site.z - Math.cos(this.baseYaw) * 0.75;
