275:   aimAt(target, dt) {
276:     if (!target) return;
277:     const from = this.worldMuzzle;
278:     const dx = target.x - from.x, dz = target.z - from.z;
279:     const dy = (target.y ?? this.site.y + 1.2) + (target.headY ?? 1.1) - from.y;
280:     const dist = Math.sqrt(dx * dx + dz * dz) || 1;
281:     const desiredYaw = Math.atan2(dx, dz) - this.baseYaw;
282:     this.yaw = dampAngle(this.yaw, clamp(desiredYaw, -0.95, 0.95), 6, dt);
283:     this.pitch = damp(this.pitch, clamp(Math.atan2(dy, dist), -0.4, 0.7), 6, dt);
284:     this.group.rotation.y = this.baseYaw + this.yaw;
285:     this.group.rotation.x = -this.pitch;
