290:     const from = this.worldMuzzle;
291:     const to = new THREE.Vector3(target.x, (target.y ?? this.site.y) + (target.headY ?? 1.2), target.z);
292:     const dist = from.distanceTo(to);
293:     const spread = clamp(dist / 500, 0.01, 0.09);
294:     to.x += (Math.random() - 0.5) * dist * spread;
295:     to.y += (Math.random() - 0.5) * dist * spread * 0.6;
