297:     const blocked = this.game.lineBlocked(from, to);
298:     if (blocked) to.copy(blocked);
299:     this.game.effects.tracer(from, to, this.team === 'british' ? 0xffe1a0 : 0xff9a55, 0.07);
300:     this.game.effects.muzzle(from, _v2.copy(to).sub(from).normalize(), 1.0);
301:     this.game.audio?.mg(this.team, from);
302:     this.ammo--;
303:     this.heat = Math.min(1, this.heat + 0.018);
304:     this.cooldown = 0.075;
305:     this.spin += 1;
306:     let chance = clamp(0.42 - dist / 320, 0.06, 0.42);
307:     if (!blocked && Math.random() < chance) {
308:       target.hit?.(9 + Math.random() * 7, from, _v3.copy(to).sub(from).normalize());
309:     } else if (Math.random() < 0.6) {
310:       this.game.effects.impactDirt(to, 0.5);
311:     }
312:   }
313: 
314:   update(dt) {
315:     this.cooldown = Math.max(0, this.cooldown - dt);
316:     this.heat = Math.max(0, this.heat - dt * 0.055);
317:     this.overheated = this.heat > 0.98;
318:     if (!this.mountedBy) {
