324:     if (!this.target || this.game.isDead(this.target)) {
325:       this.target = this.game.findTarget(this.team, this.site.x, this.site.z, 170);
326:     }
327:     if (this.target) {
328:       this.aimAt(this.target, dt);
329:       this.fireAt(this.target);
330:     }
331:   }
