348:     this.maxHp = this.hp;
349:     this.alive = true;
350:     this.crewCount = 0;
351:     this.seats = { driver: null, gunnerL: null, gunnerR: null, crew1: null, crew2: null };
352:     this.target = null;
353:     this.fireCooldown = [0, 0];
354:     this.smokeT = 0;
355:     this.trackDist = 0;
356:     this.pitch = 0; this.roll = 0;
