372: 
373:   buildCrewVisuals() {
374:     this.crewHeads = {};
375:     const spots = {
376:       driver: [1.55, 2.98, 0],
377:       gunnerL: [0.35, 2.1, 2.12],
378:       gunnerR: [0.35, 2.1, -2.12],
379:       crew1: [-1.6, 2.25, 1.0],
380:       crew2: [-1.6, 2.25, -1.0],
381:     };
382:     for (const [name, p] of Object.entries(spots)) {
383:       const g = new THREE.Group();
384:       const head = addSphere(g, 0.13, PALETTE.skin, 0, 0.12, 0, 1, 1.1, 1);
385:       const helmet = addSphere(g, 0.16, this.team === 'british' ? PALETTE.khakiDark : PALETTE.fieldgreyDark, 0, 0.2, 0, 1, 0.6, 1);
386:       const shoulders = addBox(g, 0.4, 0.18, 0.26, this.team === 'british' ? PALETTE.khaki : PALETTE.fieldgrey, 0, -0.06, 0);
387:       g.position.set(p[0], p[1], p[2]);
