393: 
394:   updateCrewVisuals() {
395:     for (const k of Object.keys(this.crewHeads)) this.crewHeads[k].visible = !!this.seats[k];
396:   }
397: 
398:   board(soldier) {
399:     const order = ['driver', 'gunnerL', 'gunnerR', 'crew1', 'crew2'];
400:     for (const seat of order) {
401:       if (!this.seats[seat]) {
402:         this.seats[seat] = soldier;
403:         soldier.inVehicle = this;
404:         soldier.group.visible = false;
405:         this.crewCount++;
