407:         this.game.hud?.message(`${soldier.team === 'british' ? 'Экипаж' : 'Экипаж'}: ${seatName(seat)} занят`, 1.4);
408:         return true;
409:       }
410:     }
411:     return false;
412:   }
413: 
414:   get operational() { return this.alive && !!this.seats.driver && !!this.seats.gunnerL && !!this.seats.gunnerR; }
415: 
416:   hit(dmg, from, dir) {
417:     if (!this.alive) return;
418:     this.hp -= dmg;
419:     this.game.effects.sparks(new THREE.Vector3(this.pos.x + (Math.random() - 0.5) * 3, this.pos.y + 1.8, this.pos.z + (Math.random() - 0.5) * 2), 5);
420:     if (this.hp <= 0) this.destroy();
