422: 
423:   destroy() {
424:     if (!this.alive) return;
425:     this.alive = false;
426:     this.game.effects.explosion(new THREE.Vector3(this.pos.x, this.pos.y + 1.6, this.pos.z), 3.2);
427:     this.game.audio?.explosion(this.pos, 1.4);
428:     this.game.onTankDestroyed(this);
429:     // kill crew
430:     for (const seat of Object.values(this.seats)) {
431:       if (seat && seat.die) seat.die(new THREE.Vector3(0, 1, 0), this.pos);
432:     }
433:     this.group.traverse((o) => { if (o.isMesh) o.material = o.material; });
434:     this.group.rotation.z = (Math.random() - 0.5) * 0.25;
435:     this.game.hud?.message('Танк уничтожен!', 2.5);
436:   }
437: 
438:   update(dt) {
439:     if (!this.alive) {
440:       this.smokeT -= dt;
441:       if (this.smokeT <= 0) {
442:         this.smokeT = 0.08;
443:         const p = this.pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 3, 2 + Math.random() * 1.2, (Math.random() - 0.5) * 2.5));
444:         this.game.effects.smoke(p, 2.4, [0.15, 0.14, 0.12], 1, 0.9, 4);
445:         if (Math.random() < 0.4) this.game.effects.fire(p);
446:       }
447:       return;
448:     }
449:     // movement
450:     const trench = trenchDepthAt(this.pos.x, this.pos.z);
451:     let speedMul = 1;
452:     if (trench > 0.6) speedMul = 0.28;
453:     if (this.stuck > 0) { speedMul = 0; this.stuck -= dt; }
454:     const targetSpeed = this.operational ? this.desiredSpeed ?? 0 : 0;
455:     this.speed = damp(this.speed, targetSpeed * speedMul, 1.6, dt);
456:     if (Math.abs(this.speed) > 0.05) {
457:       this.pos.x += Math.sin(this.yaw) * this.speed * dt;
458:       this.pos.z += Math.cos(this.yaw) * this.speed * dt;
459:       this.trackDist += this.speed * dt;
460:       this.moving = true;
461:     } else this.moving = false;
462:     // steering
463:     if (this.steer) this.yaw += this.steer * dt * 0.5 * clamp(Math.abs(this.speed) / 2, 0.2, 1);
464:     this.pos.x = clamp(this.pos.x, WORLD.minX + 10, WORLD.maxX - 10);
465:     this.pos.z = clamp(this.pos.z, WORLD.minZ + 10, WORLD.maxZ - 10);
466: 
467:     // terrain fit
468:     const f = Math.sin(this.yaw), c = Math.cos(this.yaw);
469:     const hx = 3.3, hz = 1.8;
470:     const hf = heightAt(this.pos.x + f * hx, this.pos.z + c * hx);
471:     const hb = heightAt(this.pos.x - f * hx, this.pos.z - c * hx);
472:     const hl = heightAt(this.pos.x + c * hz, this.pos.z - f * hz);
473:     const hr = heightAt(this.pos.x - c * hz, this.pos.z + f * hz);
474:     const avg = (hf + hb + hl + hr) / 4;
475:     this.pos.y = damp(this.pos.y, avg + 0.06, 8, dt);
476:     this.pitch = damp(this.pitch, Math.atan2(hb - hf, hx * 2), 5, dt);
477:     this.roll = damp(this.roll, Math.atan2(hl - hr, hz * 2), 5, dt);
478:     this.group.position.copy(this.pos);
479:     this.group.rotation.set(this.pitch, this.yaw, this.roll);
480:     this.group.updateMatrixWorld(true);
481: 
482:     // track plates
483:     for (const tr of this.tracks) {
484:       const n = tr.path.length;
485:       const dummy = this._dummy || (this._dummy = new THREE.Object3D());
486:       for (let i = 0; i < tr.plates.count; i++) {
487:         const idx = ((i + Math.floor(this.trackDist * 4)) % n + n) % n;
488:         const p = tr.path[idx];
