  revets.castShadow = true; revets.receiveShadow = true;
  let ri = 0;

  const postGeo = new THREE.BoxGeometry(0.09, 1.25, 0.09);
  const posts = new THREE.InstancedMesh(postGeo, toonMat(PALETTE.woodDark), 2200);
