  /* ---------------- tank park ---------------- */
  buildTankPark() {
    const { x, z } = WORLD.tankSpawn;
    for (let i = 0; i < 6; i++) {
      const dx = x - 22 + (i % 3) * 8, dz = z - 14 + Math.floor(i / 3) * 7;
