521: function wing(parent, span, chord, thick, y, z, color, mat, dihedral = 0) {
522:   const geo = new THREE.BoxGeometry(span, thick, chord, 16, 1, 4);
523:   // round the wing tips
524:   const pos = geo.attributes.position;
525:   for (let i = 0; i < pos.count; i++) {
526:     const x = pos.getX(i);
527:     const tip = Math.max(0, (Math.abs(x) - span * 0.36) / (span * 0.14));
528:     if (tip > 0) {
529:       const f = Math.max(0.05, 1 - tip * 0.9);
530:       pos.setZ(i, pos.getZ(i) * f);
531:       pos.setY(i, pos.getY(i) * (0.5 + f * 0.5));
532:     }
533:     pos.setY(i, pos.getY(i) + Math.abs(x) / span * dihedral);
534:   }
535:   geo.computeVertexNormals();
536:   const m = new THREE.Mesh(geo, mat || toonMat(color));
537:   m.position.set(0, y, z);
538:   m.castShadow = true; m.receiveShadow = true;
539:   parent.add(m);
540:   return m;
