  const p = this.player;
  const show = p.mode === 'foot' && !p.dead;
  const name = p.slot === 1 ? 'shovel' : p.slot === 2 ? 'hammer' : 'rifle';
  for (const [key, vm] of Object.entries(this.viewmodels)) vm.visible = show && key === name;
